import 'dart:js_interop';

import 'package:web/web.dart' as web;

import 'idb_request_future.dart';

/// Owns the single AES-GCM master key that encrypts everything in the web
/// secure-storage vault.
///
/// The key is generated by WebCrypto as **non-extractable** and persisted in
/// IndexedDB by structured clone. Page script (including an attacker's XSS) can
/// therefore USE the key while the page is open but can never read its raw
/// bytes or copy it out of the browser profile — unlike the stock
/// `flutter_secure_storage_web`, which derives its key from a constant.
class WebVaultKey {
  WebVaultKey(this._db);

  static const String storeName = 'meta';
  static const String _keyId = 'master-aes-gcm-v1';

  final web.IDBDatabase _db;
  web.CryptoKey? _cached;

  /// Returns the existing master key, creating and persisting it on first use.
  Future<web.CryptoKey> load() async {
    final cached = _cached;
    if (cached != null) return cached;

    final existing = await idbRequestFuture(
      _db.transaction(storeName.toJS, 'readonly').objectStore(storeName).get(
            _keyId.toJS,
          ),
    );
    if (existing != null && !existing.isUndefinedOrNull) {
      return _cached = existing as web.CryptoKey;
    }

    final algorithm = {'name': 'AES-GCM', 'length': 256}.jsify()!;
    final usages = <JSString>['encrypt'.toJS, 'decrypt'.toJS].toJS;
    final generated = await web.window.crypto.subtle
        .generateKey(algorithm, false, usages)
        .toDart as web.CryptoKey;

    final tx = _db.transaction(storeName.toJS, 'readwrite');
    tx.objectStore(storeName).put(generated, _keyId.toJS);
    await idbTransactionDone(tx);
    return _cached = generated;
  }
}
